# Operator → list of lines (operator string as tagged in OSM, lowercased / collapsed whitespace).
import re as _re
def _norm_op(s): return _re.sub(r'\s+', ' ', (s or '').strip().lower())
TRANSMISSION_LINES_BY_OPERATOR: dict[str, list[dict]] = {}
for _l in TRANSMISSION_LINES:
    _k = _norm_op(_l['operator'])
    if _k:
        TRANSMISSION_LINES_BY_OPERATOR.setdefault(_k, []).append(_l)
